<script setup lang="ts">
import { onMounted,onUnmounted,ref,computed,watch } from 'vue';
import { Download, ArrowRight, LoaderCircle } from 'lucide-vue-next';
import type { Product,CollectionJob } from '../../../../packages/contracts/index';
import {api,post,download} from '../api';
const props=defineProps<{products:Product[];admin:boolean}>();
const emit=defineEmits<{use:[data:{csv:string;productId:string;url:string;platform:string}];products:[items:Product[]]}>();
const platform=ref<'jd'|'tmall'>('jd');const productId=ref('');const url=ref('');const limit=ref(50);const query=ref('');const jobs=ref<CollectionJob[]>([]);const error=ref('');const busy=ref(false);
const availableProducts=ref<Product[]>(props.products);const productName=ref('');const createdNotice=ref('');let autoSelected=false;
watch(()=>props.products,items=>availableProducts.value=items);
watch(url,()=>{createdNotice.value='';if(autoSelected){productId.value='';autoSelected=false;}});
const searchUrl=computed(()=>platform.value==='jd'?`https://search.jd.com/Search?keyword=${encodeURIComponent(query.value+' 蓝牙耳机')}`:`https://list.tmall.com/search_product.htm?q=${encodeURIComponent(query.value+' 蓝牙耳机')}`);
const names={queued:'等待中',running:'采集中',waiting:'等待浏览器操作',completed:'已结束',partial:'部分完成',blocked:'平台访问受限',failed:'采集失败'};
async function refresh(){try{const [items,records]=await Promise.all([api<Product[]>('/products'),props.admin?api<CollectionJob[]>('/collections'):Promise.resolve([])]);availableProducts.value=items;emit('products',items);jobs.value=records;}catch(e){error.value=(e as Error).message;}}
async function start(method:'public'|'browser'='public'){busy.value=true;error.value='';try{const creating=!productId.value;const job=await post<CollectionJob>('/collections',{method,platform:platform.value,...(productId.value?{productId:productId.value}:{}),productName:productName.value.trim()||query.value.trim()||undefined,url:url.value,limit:limit.value});await refresh();productId.value=job.productId;autoSelected=creating;if(creating)createdNotice.value=`已关联 ${availableProducts.value.find(p=>p.id===job.productId)?.name??job.productId}，采集任务已创建。`;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function use(job:CollectionJob){try{emit('use',await api(`/collections/${job.id}/data`));}catch(e){error.value=(e as Error).message;}}
async function save(job:CollectionJob){try{await download(`/collections/${job.id}/csv`,`${job.platform}-${job.itemId}-评论.csv`);}catch(e){error.value=(e as Error).message;}}
async function finishBrowser(job:CollectionJob){try{await post(`/collections/${job.id}/finish`,{});await refresh();}catch(e){error.value=(e as Error).message;}}
const reading=ref<number|null>(null);
async function readBrowser(job:CollectionJob){reading.value=job.id;error.value='';try{const r=await post<{added:number;total:number}>(`/collections/${job.id}/read`,{});createdNotice.value=`本页新增${r.added}条，累计${r.total}条。`;await refresh();}catch(e){error.value=(e as Error).message;}finally{reading.value=null;}}
async function autoBrowser(job:CollectionJob){error.value='';try{await post(`/collections/${job.id}/auto`,{});createdNotice.value='已开始自动读取和翻页，完成后可下载CSV或预览导入。';await refresh();}catch(e){error.value=(e as Error).message;}}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{void refresh();window.addEventListener('focus',refresh);timer=setInterval(()=>{if(jobs.value.some(j=>j.status==='running'||j.status==='queued'||j.status==='waiting'))void refresh();},2000);});onUnmounted(()=>{clearInterval(timer);window.removeEventListener('focus',refresh);});
</script>
<template>
  <div class="page-heading"><div><h1>获取平台评论</h1><p>指定具体商品，尝试采集公开评论并转换为 CSV。</p></div></div>
  <p class="data-note">系统自动打开采集专用Chrome，保留该窗口的登录状态。首次请在窗口中正常登录或完成验证，进入评价区后点击“开始自动采集”，系统读取评论并尝试翻页、生成CSV。无需扩展或配对码。也可手动翻页后读取当前页。每次最多100条、10页；登录过期需重新登录。</p>
  <div v-if="!admin" class="panel empty-state"><h2>登录后采集到你的耳机记录</h2><p>先到评论导入页登录，返回后可直接用商品链接创建采集任务。</p><RouterLink to="/data" class="primary">前往登录</RouterLink></div>
  <template v-else>
    <form class="panel collection-form" @submit.prevent="start('public')"><div class="form-grid"><label>来源平台<select v-model="platform" aria-label="来源平台"><option value="jd">京东</option><option value="tmall">天猫</option></select></label><label>目标耳机<select v-model="productId" aria-label="目标耳机" @change="autoSelected=false"><option value="">按商品链接自动创建耳机</option><option v-for="p in availableProducts" :key="p.id" :value="p.id">{{ p.name }}</option></select></label></div><p class="subtle">没有目标耳机也可采集：填写名称和商品链接，系统会创建并关联耳机。已有记录可直接选择。<button type="button" class="text-button" @click="refresh">刷新耳机列表</button></p><label v-if="!productId">耳机名称（可选）<input v-model="productName" maxlength="80" placeholder="例如：华为 FreeClip；留空使用搜索词或商品编号"/></label><label>在平台查找耳机<div class="collection-search"><input v-model="query" maxlength="80" placeholder="例如：品牌 + 型号"/><a :href="searchUrl" target="_blank" rel="noopener noreferrer" class="secondary">打开平台搜索</a></div></label><label>商品详情页链接或商品编号<input v-model="url" required maxlength="1000" :placeholder="platform==='jd'?'https://item.jd.com/商品编号.html':'https://detail.tmall.com/item.htm?id=商品编号'"/></label><div class="collection-actions"><label>最多采集条数<input v-model.number="limit" type="number" min="1" max="100" required/></label><button type="button" class="primary" :disabled="busy||jobs.some(j=>['running','waiting'].includes(j.status))" @click="start('browser')">打开 Chrome 辅助采集</button><button class="secondary" :disabled="busy||jobs.some(j=>['running','waiting'].includes(j.status))"><LoaderCircle v-if="busy" :size="16" class="spin"/>{{ busy?'创建任务…':'开始公开采集' }}</button></div></form>
    <p v-if="createdNotice" class="message success" role="status">{{ createdNotice }}</p><div v-if="error" class="message error" role="alert">{{ error }}</div>
    <div class="section-heading"><h2>采集记录</h2><button class="text-button" @click="refresh">刷新</button></div><section class="panel"><div v-if="!jobs.length" class="empty-state compact">提交商品链接后，这里显示采集进度与 CSV。</div><div v-for="job in jobs" :key="job.id" class="collection-row"><div><strong>{{ availableProducts.find(p=>p.id===job.productId)?.name }}</strong><p class="subtle">{{ job.platform==='jd'?'京东':'天猫' }} · {{ job.method==='browser'?'浏览器辅助':'匿名尝试' }} · 商品 {{ job.itemId }} · {{ names[job.status] }}</p><p v-if="job.error" class="error-text">{{ job.error }}</p></div><span>{{ job.total }} 条已采集</span><template v-if="job.method==='browser'&&job.status==='waiting'"><button class="primary small" @click="autoBrowser(job)">开始自动采集</button><button class="secondary small" :disabled="reading!==null" @click="readBrowser(job)">{{ reading===job.id ? '读取中…' : '读取当前评论页' }}</button><button class="primary small"  @click="finishBrowser(job)">结束并生成 CSV</button></template><template v-if="job.total>0&&['completed','partial'].includes(job.status)"><button class="secondary small" @click="save(job)"><Download :size="15"/>下载 CSV</button><button class="primary small" @click="use(job)">预览并导入<ArrowRight :size="15"/></button></template><RouterLink v-if="['blocked','failed'].includes(job.status)" class="text-button" to="/data">改用已有 CSV</RouterLink></div></section>
  </template>
</template>
